-- Rehearsal-only planning scaffold; no approval, media, publication or actual learner writes.
DO $qa$ DECLARE o record; t record; d record; s record; a uuid; tr uuid; BEGIN
 IF current_setting('neon.project_id',true) IS DISTINCT FROM 'sweet-hall-62441909' OR current_setting('neon.branch_id',true) IS DISTINCT FROM 'br-solitary-art-arun91gj' THEN RAISE EXCEPTION 'Dedicated QA branch required'; END IF;
 SELECT * INTO STRICT o FROM public.organizations WHERE metadata->>'qa_fixture_key'='pilot1-api-rehearsal-v1' AND metadata->>'qa_only'='true' AND metadata->>'intended_branch'=current_setting('neon.branch_id',true);
 SELECT nt.id,nt.author_person_id,nt.offering_version_id,ov.offering_id,oc.course_version_id,cv.course_id INTO STRICT t FROM public.noncredit_training_versions nt JOIN public.offering_versions ov ON ov.id=nt.offering_version_id JOIN public.offering_courses oc ON oc.offering_version_id=ov.id JOIN public.course_versions cv ON cv.id=oc.course_version_id WHERE nt.provider_organization_id=o.id AND nt.state='draft' AND ov.lifecycle='draft' AND cv.lifecycle='draft';
 SELECT * INTO STRICT d FROM public.program_deployments WHERE offering_id=t.offering_id AND status='planning';
 SELECT * INTO STRICT s FROM public.sites WHERE organization_id=o.id AND lifecycle_status='planning';
 IF NOT EXISTS(SELECT 1 FROM public.people WHERE id=t.author_person_id AND metadata->>'qa_fixture_key'='pilot1-api-rehearsal-v1' AND metadata->>'qa_only'='true' AND metadata->>'intended_branch'=current_setting('neon.branch_id',true)) THEN RAISE EXCEPTION 'Unverified QA author'; END IF;
 IF NOT EXISTS(SELECT 1 FROM public.education_operation_organization_roles WHERE operation_id=d.operation_id AND organization_id=o.id AND role_code='operator') THEN INSERT INTO public.education_operation_organization_roles(operation_id,organization_id,role_code,valid_from,status) VALUES(d.operation_id,o.id,'operator',now(),'proposed'); END IF;
 IF NOT EXISTS(SELECT 1 FROM public.education_operation_sites WHERE operation_id=d.operation_id AND site_id=s.id) THEN INSERT INTO public.education_operation_sites(operation_id,site_id,valid_from,purpose) VALUES(d.operation_id,s.id,now(),'QA planning only'); END IF;
 SELECT id INTO a FROM public.deployment_offering_adoptions WHERE deployment_id=d.id AND offering_version_id=t.offering_version_id AND approval_status='proposed';
 IF a IS NULL THEN INSERT INTO public.deployment_offering_adoptions(deployment_id,offering_id,offering_version_id,valid_from,approval_status) VALUES(d.id,t.offering_id,t.offering_version_id,now(),'proposed') RETURNING id INTO a; END IF;
 IF NOT EXISTS(SELECT 1 FROM public.classes WHERE deployment_id=d.id AND adoption_id=a AND course_version_id=t.course_version_id) THEN INSERT INTO public.classes(deployment_id,adoption_id,offering_version_id,course_version_id,operating_organization_id,site_id,title,capacity,delivery_mode,state,created_by_person_id) VALUES(d.id,a,t.offering_version_id,t.course_version_id,o.id,s.id,'TEST ONLY - Community Decision-Making',10,'self_paced','draft',t.author_person_id); END IF;
 SELECT id INTO tr FROM public.instructional_tracks WHERE course_id=t.course_id AND producer_organization_id=o.id AND title='QA rehearsal instructor';
 IF tr IS NULL THEN INSERT INTO public.instructional_tracks(course_id,presenter_person_id,producer_organization_id,title) VALUES(t.course_id,t.author_person_id,o.id,'QA rehearsal instructor') RETURNING id INTO tr; END IF;
 IF NOT EXISTS(SELECT 1 FROM public.instructional_track_versions WHERE instructional_track_id=tr AND course_version_id=t.course_version_id) THEN INSERT INTO public.instructional_track_versions(instructional_track_id,course_version_id,course_id,created_by_person_id,version_no,lifecycle,track_kind) VALUES(tr,t.course_version_id,t.course_id,t.author_person_id,1,'draft','primary'); END IF;
 END $qa$;
